#include "nqueens.h"

#include <array>
#include <cstdint>

namespace {

using Mask = std::uint32_t;

constexpr int kMinBoardSize = 4;
constexpr int kMaxBoardSize = 12;
// Known counts size the output buffer. Every solution is still generated by the search.
constexpr std::array<int, 9> kSolutionCounts = {2, 10, 4, 40, 92, 352, 724, 2680, 14200};

struct Search {
  int n;
  Mask boardMask;
  std::array<int, kMaxBoardSize> columnAtRow;
  std::vector<std::vector<int>> solutions;

  template <bool AddReflection>
  void visit(int row, Mask columns, Mask diagonalLeft, Mask diagonalRight) {
    if (row == n) {
      solutions.emplace_back(columnAtRow.begin(), columnAtRow.begin() + n);
      if constexpr (AddReflection) {
        auto& reflected = solutions.emplace_back(n);
        for (int r = 0; r < n; ++r) {
          reflected[r] = n - 1 - columnAtRow[r];
        }
      }
      return;
    }

    Mask available = boardMask & ~(columns | diagonalLeft | diagonalRight);
    while (available != 0) {
      const int column = __builtin_ctz(available);
      const Mask queen = Mask{1} << column;
      available ^= queen;

      columnAtRow[row] = column;
      // Shift diagonal attacks by one column to project them onto the next row.
      visit<AddReflection>(row + 1, columns | queen, (diagonalLeft | queen) << 1,
                           (diagonalRight | queen) >> 1);
    }
  }
};

}  // namespace

std::vector<std::vector<int>> solveNQueens(int n) {
  if (n < kMinBoardSize || n > kMaxBoardSize) {
    return {};
  }

  Search search{n, (Mask{1} << n) - 1, {}, {}};
  search.solutions.reserve(kSolutionCounts[n - kMinBoardSize]);

  for (int column = 0; column < n / 2; ++column) {
    search.columnAtRow[0] = column;
    const Mask queen = Mask{1} << column;
    search.visit<true>(1, queen, queen << 1, queen >> 1);
  }

  // For odd boards, both sides of a reflected pair can start in the center column.
  if (n % 2 != 0) {
    const int center = n / 2;
    search.columnAtRow[0] = center;
    const Mask queen = Mask{1} << center;
    search.visit<false>(1, queen, queen << 1, queen >> 1);
  }

  return std::move(search.solutions);
}
